{"file_path":"src/schedule.js","content":"/**
 * Timing, wave-depth and worker-packing computations over a parsed build
 * graph. The graph is guaranteed acyclic by the time these run.
 */

/**
 * Computes, for every task, its wave (structural dependency depth), start
 * time and finish time, all memoized over the acyclic dependency graph.
 */
export function computeTimings(graph) {
  const { tasks, deps } = graph
  const wave = new Map()
  const start = new Map()

  function waveOf(name) {
    if (wave.has(name)) return wave.get(name)
    const depSet = deps.get(name)
    const value = depSet.size === 0 ? 0 : 1 + Math.max(...[...depSet].map(waveOf))
    wave.set(name, value)
    return value
  }

  function startOf(name) {
    if (start.has(name)) return start.get(name)
    const depSet = deps.get(name)
    const value = depSet.size === 0 ? 0 : Math.max(...[...depSet].map((dep) => startOf(dep) + tasks.get(dep)))
    start.set(name, value)
    return value
  }

  const result = new Map()
  for (const name of tasks.keys()) {
    const s = startOf(name)
    result.set(name, { start: s, finish: s + tasks.get(name), depth: waveOf(name) })
  }
  return result
}

/** The unlimited-worker makespan: the greatest finish time, or 0 when there is no task. */
export function totalOf(timings) {
  let total = 0
  for (const { finish } of timings.values()) total = Math.max(total, finish)
  return total
}

/** Groups task names into waves, each wave's names sorted ascending. */
export function groupWaves(timings) {
  const waves = []
  for (const [name, { depth }] of timings) {
    if (!waves[depth]) waves[depth] = []
    waves[depth].push(name)
  }
  for (const wave of waves) wave.sort()
  return waves
}

/**
 * Simulates the graph on a fixed number of workers using the greedy,
 * priority-ordered list-scheduling rule the specification describes.
 * Returns `{ workers, makespan }`, where `workers[i]` is the ordered list
 * of `{ name, start, finish }` entries worker `i` ran.
 */
export function pack(graph, workerCount) {
  const { tasks, deps } = graph

  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, new Set())
  for (const [name, depSet] of deps) {
    for (const dep of depSet) dependents.get(dep).add(name)
  }

  const priority = new Map()
  function priorityOf(name) {
    if (priority.has(name)) return priority.get(name)
    const succs = dependents.get(name)
    const value = tasks.get(name) + (succs.size === 0 ? 0 : Math.max(...[...succs].map(priorityOf)))
    priority.set(name, value)
    return value
  }
  for (const name of tasks.keys()) priorityOf(name)

  const finished = new Map() // name -> finish time, once started
  const pending = new Set(tasks.keys())
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, log: [] }))

  const isReady = (name, t) => {
    for (const dep of deps.get(name)) {
      if (!finished.has(dep) || finished.get(dep) > t) return false
    }
    return true
  }

  let t = 0
  while (pending.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      const freeIndex = workers.findIndex((w) => w.busyUntil <= t)
      if (freeIndex === -1) break

      let best = null
      for (const name of pending) {
        if (!isReady(name, t)) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const cost = tasks.get(best)
      const finish = t + cost
      workers[freeIndex].busyUntil = finish
      workers[freeIndex].log.push({ name: best, start: t, finish })
      finished.set(best, finish)
      pending.delete(best)
      progressed = true
    }

    if (pending.size === 0) break

    const nextEvents = workers.map((w) => w.busyUntil).filter((busyUntil) => busyUntil > t)
    t = Math.min(...nextEvents)
  }

  let makespan = 0
  for (const finish of finished.values()) makespan = Math.max(makespan, finish)

  return { workers: workers.map((w) => w.log), makespan }
}
"}

