/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError, parseGraph, findCycle } from './parse.js'
import { computeTimings, totalOf, groupWaves, pack } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKER_COUNT_PATTERN = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKER_COUNT_PATTERN.test(argv[1])) {
      throw new CliError(2, 'workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(2, USAGE)
}

function runWaves(graph) {
  const timings = computeTimings(graph)
  const waves = groupWaves(timings)
  const lines = waves.map((names, depth) => `wave ${depth}: ${names.join(' ')}`)
  lines.push(`total ${totalOf(timings)}`)
  return lines.join('\n') + '\n'
}

function runExplain(graph) {
  const timings = computeTimings(graph)
  const names = [...timings.keys()].sort()
  const lines = names.map((name) => {
    const { start, finish, depth } = timings.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  lines.push(`total ${totalOf(timings)}`)
  return lines.join('\n') + '\n'
}

