  const { workers, makespan } = pack(graph, workerCount)
  const lines = workers.map((log, i) => {
    const entries = log.map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    return `worker ${i}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  let args
  try {
    args = parseArgs(process.argv.slice(2))
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(err.exitCode)
    }
    throw err
  }

  const input = readFileSync(0, 'utf8')

  let graph
  try {
    graph = parseGraph(input)
    const cycle = findCycle(graph)
    if (cycle) throw new CliError(3, `cycle: ${cycle.join(' -> ')}`)
